  const O = 'Odette Thorne', cost = 60 + 25 * S.lvl, since = S.flags.lastMurderDay == null ? 99 : S.day - S.flags.lastMurderDay, calm = since >= 2, wait = since <= 0 ? 'two days' : 'one more day';
