  if (qAt('q_warden', 1)) { const mine = lineLinked();
    return say([[O, 'The Warden. Then the tomb of 1864 is open all the way down, and what he sat on top of is awake.'], [O, "Emeline's seal let the dead walk in and never out. My grandmother lowered it, and it stopped her heart. Since then, what goes down can come back up."], [O, 'His name is Corvin. He is one of the first family: a thousand years old, vampire and wolf both. Half the vampires in this county were made by something he made. Ambrose Varga. Most of the nest in the quarry. Every newborn in the cemetery.' + (mine ? ' You.' : '')], [O, 'Locks never held him. A Thorne stopped his heart with her hand on his chest, and a living heart stopped to pay for it. He lay grey down there until the Hollow cultists started carrying blood to him.'],
      [O, 'Nothing kills him but white oak. And if white oak does kill him, everything of his line dies within the hour.' + (mine ? ' That means you. Hear me: if Corvin truly dies while you are tied to him, you die too. I can cut that tie, with his blood. The Cure would do it as well.' : ' Ambrose would be dead on his bridge before you had climbed back up.')], [O, 'There is another way. Put him on the floor, say my name with your hand on him, and I will come down and stop his heart again. It costs what it cost the last time. Talk to Hale about the first way. Go armed.']], null, () => { F.desicReady = 1; if (!F.corvinAwake) F.corvinAwake = S.day; jot('original', 'sireline', 'desicspell'); qEvent('talk', 'odette'); }); }
