  if (S.done.q_witch && S.lvl >= 9 && !S.quests.q_hollow && !S.done.q_hollow) opts.push(['"Tell me about Coven Hollow."', () => say([[O, 'North, past the chapel road. A hundred of us were burned there in one night. They never left.'], [O, canMagic() && !vamp ? 'A living witch can lean on them. Lay a hand on the altar and they lend you all hundred at once. It comes out of you in blood, and too long would kill you.' : vamp ? 'They hate what you are. On their ground a daylight ring stops working and they will hurt you, unless a witch they trust has spoken for you.' : 'They lend their strength to living witches. They have nothing to give anyone else, and nothing against you either.'], [O, 'Lately something answers there after dark that is not a hundred women. It is one voice. The cultists at the chapel have been pulling on them until they ran together. Lay a hand on the altar at night, call it out, and break it.']], null, () => { jot('hundred', 'otherside'); startQuest('q_hollow'); })]);
