  if (S.lvl >= 12 && !tr && S.done.q_bridge) opts.push(['"Fight me."', () => say([[A, vamp ? 'I wondered when you would ask. To the first fall. Try not to disappoint me.' : 'I have not been struck by the living in sixty years. To the first fall. Please.'], [A, 'I will yield when I have had enough. If I am on the ground and you put wood through my heart, that is not a duel any more. Mind where you put it.']], null, () => { const e = spawnEnemy('ambrose', n.x, n.z, Math.max(14, S.lvl + 1)); e.rot = n.rot; e.duel = 1; n.rig.g.visible = false; aggro(e); })]);
