  if (who === 'own') pl.hp = Math.max(1, pl.hp - P.maxHp * 0.35); else if (who === 'you') { F.odetteSpent = S.day + 4; pl.hp = Math.max(1, P.maxHp * 0.2); } else if (who === 'elise') { F.odetteSpent = S.day + 4; F.eliseRest = S.day + 4; }
